/**
 * dsh-pet-hermes 简版设置卡 — 一级设置页（settings.section 席位）。
 * 参考原 @linxin666/dsh-pet 的 PetSettingsCard 结构，但简化：硬编码中文
 * label、不搬 locale 系统、不搬完整卡片 chrome。字段读写走 SettingsScope
 * （scope.set/unset 真正写 ~/.dsh/settings.yaml 的 pet-hermes: 段，立即生效）。
 * @module dsh-pet-hermes/client/PetHermesSettingsCard
 */

import { useEffect, useRef, useState, type ReactElement } from 'react'
import type { SettingsScope, SettingsScopeSnapshot } from '@deepseek-ai/dsh-client-runtime/client'
import styles from './settings-card.module.css'

/** pet-hermes 的 settings namespace 值（host makeSettingsSchema 的解析结果）。 */
export interface PetHermesSettingsValue {
  enabled: boolean
  endpoint: string
  model: string
  tokenFile: string
  persona: string
  maxHistory: number
  timeoutMs: number
}

/** 一个表单字段的定义。 */
interface FieldDef {
  key: keyof PetHermesSettingsValue
  label: string
  hint: string
  kind: 'boolean' | 'number' | 'text'
  /** number 字段的约束。 */
  min?: number
  max?: number
  integer?: boolean
}

/** pet-hermes 的字段列表（顺序 = 卡片渲染顺序）。 */
const FIELDS: FieldDef[] = [
  { key: 'enabled', label: '启用桌宠', hint: '关闭后右下角不显示桌宠（设置卡仍可见）', kind: 'boolean' },
  { key: 'endpoint', label: 'Hermes API 地址', hint: 'Hermes 的 OpenAI 兼容网关基址，如 http://127.0.0.1:8642', kind: 'text' },
  { key: 'model', label: '模型名', hint: '/v1/models 里的 model id，如 hermes-agent', kind: 'text' },
  { key: 'persona', label: '人设（system prompt）', hint: '留空用内置鲸鱼娘人设；每轮对话前 prepend', kind: 'text' },
  { key: 'maxHistory', label: '历史轮数上限', hint: '每轮转发给 Hermes 的最大消息数（1-200）', kind: 'number', min: 1, max: 200, integer: true },
  { key: 'timeoutMs', label: '请求超时（毫秒）', hint: '单次对话的超时上限（1000-600000）', kind: 'number', min: 1000, max: 600000, integer: true },
]

/** 设置卡 props：绑定的 scope（由 client/index.ts 提供）。 */
export interface PetHermesSettingsCardProps {
  scope: SettingsScope<PetHermesSettingsValue>
}

/**
 * 简版设置卡：staged 表单 + 保存/丢弃。
 * 用户改字段只是 staged，点"保存"才调 scope.set/unset 真正写 settings.yaml。
 * 写成功后 host 的 getConfig() 下次请求读到新值 → 立即生效。
 */
export function PetHermesSettingsCard(props: PetHermesSettingsCardProps): ReactElement {
  const { scope } = props
  const [snapshot, setSnapshot] = useState<SettingsScopeSnapshot<PetHermesSettingsValue>>(() => scope.getSnapshot())
  // staged 草稿：key → 用户输入的文字（未保存）
  const [drafts, setDrafts] = useState<Record<string, string>>({})
  const [saving, setSaving] = useState(false)
  const [failed, setFailed] = useState<string | null>(null)
  const dirtyRef = useRef(false)

  // 订阅 scope 变化（host 写入后 snapshot 更新，卡片同步）
  useEffect(() => {
    return scope.subscribe(() => {
      setSnapshot(scope.getSnapshot())
      // host 状态变化时清掉 stale 草稿
      setDrafts({})
      setFailed(null)
    })
  }, [scope])

  // 当前生效值（scope 的 resolved section）
  const value: PetHermesSettingsValue | undefined = snapshot.value
  const available = snapshot.status === 'ready'
  const writable = snapshot.writable

  /** 读一个字段当前的显示文字（有 staged 草稿用草稿，否则用生效值）。 */
  const displayText = (def: FieldDef): string => {
    if (drafts[def.key] !== undefined) return drafts[def.key]
    if (value === undefined) return ''
    const v = value[def.key]
    if (typeof v === 'boolean') return v ? 'true' : 'false'
    if (typeof v === 'number') return String(v)
    if (typeof v === 'string') return v
    return ''
  }

  /** 字段是否 dirty（草稿 ≠ 当前生效值）。 */
  const isDirty = (def: FieldDef): boolean => {
    const d = drafts[def.key]
    if (d === undefined) return false
    const cur = value === undefined ? '' : String(value[def.key] ?? '')
    return d !== cur
  }

  const anyDirty = FIELDS.some(isDirty)

  /** 解析一个字段的草稿成写入值，非法返回 undefined。 */
  const parseDraft = (def: FieldDef, text: string): unknown | 'clear' | undefined => {
    const trimmed = text.trim()
    if (trimmed === '') return 'clear'
    if (def.kind === 'boolean') {
      if (trimmed === 'true') return true
      if (trimmed === 'false') return false
      return undefined
    }
    if (def.kind === 'number') {
      const n = Number(trimmed)
      if (!Number.isFinite(n)) return undefined
      if (def.integer && !Number.isInteger(n)) return undefined
      if (def.min !== undefined && n < def.min) return undefined
      if (def.max !== undefined && n > def.max) return undefined
      return n
    }
    // text
    return trimmed
  }

  /** 保存：对每个 dirty 字段调 scope.set/unset。 */
  const save = async (): Promise<void> => {
    if (!anyDirty || saving) return
    setSaving(true)
    setFailed(null)
    let ok = true
    for (const def of FIELDS) {
      if (!isDirty(def)) continue
      const parsed = parseDraft(def, drafts[def.key] ?? '')
      try {
        if (parsed === undefined) {
          setFailed(`字段「${def.label}」的值不合法，未保存`)
          ok = false
          continue
        }
        if (parsed === 'clear') {
          await scope.unset(def.key)
        } else {
          await scope.set(def.key, parsed)
        }
      } catch (error) {
        setFailed(`保存「${def.label}」失败：` + (error instanceof Error ? error.message : String(error)))
        ok = false
      }
    }
    if (ok) {
      // 全部成功：清草稿（scope.subscribe 会因 host 写入而更新 snapshot）
      setDrafts({})
    }
    setSaving(false)
  }

  /** 丢弃：清所有草稿。 */
  const discard = (): void => {
    setDrafts({})
    setFailed(null)
  }

  const setDraft = (key: string, text: string): void => {
    setDrafts((prev) => ({ ...prev, [key]: text }))
  }

  // namespace 未 ready（host 没暴露 / 还在加载）：显示提示
  if (!available) {
    return (
      <div className={styles.card}>
        <div className={styles.header}>
          <span className={styles.name}>Hermes 桌宠</span>
        </div>
        <div className={styles.body}>
          <p className={styles.hint}>
            {snapshot.status === 'loading' ? '设置加载中…' : '当前部署未向本客户端暴露 pet-hermes 设置（namespace 不可用）'}
          </p>
        </div>
      </div>
    )
  }

  return (
    <div className={styles.card}>
      <div className={styles.header}>
        <span className={styles.name}>Hermes 桌宠</span>
        <span className={styles.description}>dsh-pet-hermes 的对话与连接设置</span>
        {anyDirty && <span className={styles.pending}>有未保存修改</span>}
      </div>
      <div className={styles.body}>
        {!writable && <p className={styles.readOnly} role="status">当前 settings 文档只读，无法保存修改。</p>}
        {FIELDS.map((def) => {
          const text = displayText(def)
          const dirty = isDirty(def)
          return (
            <div className={styles.field} key={String(def.key)}>
              <div className={styles.head}>
                <label className={styles.label} htmlFor={'ph-' + String(def.key)}>{def.label}</label>
                {dirty && (
                  <span className={styles.badge}>已修改</span>
                )}
              </div>
              {def.kind === 'boolean' ? (
                <select
                  id={'ph-' + String(def.key)}
                  className={styles.select}
                  value={text}
                  disabled={!writable || saving}
                  onChange={(e) => { setDraft(def.key, e.target.value) }}
                >
                  <option value="">继承默认</option>
                  <option value="true">开</option>
                  <option value="false">关</option>
                </select>
              ) : (
                <input
                  id={'ph-' + String(def.key)}
                  className={styles.input}
                  type="text"
                  {...(def.kind === 'number' ? { inputMode: 'numeric' as const } : {})}
                  value={text}
                  disabled={!writable || saving}
                  onChange={(e) => { setDraft(def.key, e.target.value) }}
                />
              )}
              <p className={styles.hint}>{def.hint}</p>
            </div>
          )
        })}
        {failed !== null && (
          <p className={styles.failed} role="status">{failed}</p>
        )}
        <div className={styles.footer}>
          <button
            type="button"
            className={styles.discard}
            disabled={!anyDirty || saving}
            onClick={discard}
          >
            丢弃
          </button>
          <button
            type="button"
            className={styles.save}
            disabled={!anyDirty || saving || !writable}
            onClick={() => { void save() }}
          >
            {saving ? '保存中…' : '保存'}
          </button>
        </div>
      </div>
    </div>
  )
}
